const flush=()=>new Promise(resolve=>setImmediate(resolve));

test('a demanded attack clip survives strike rollover and stays reusable after the actor stops attacking',async()=>{
 for(const nextStatus of ['attacking','walking']){
  const animal={id:'a',species:'hyena',status:'attacking',animation:'Weapon_Combo',attackId:'first'},state={raid:{animals:[animal]}},installed=new Set(),root=new Group();let finish,attempts=0,loads=0;
  const roster=createWebGpuAnimalRoster({scene:new Scene(),residency:{},state,assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedAttackBank:{get:async(_species,clip)=>{loads++;return {meta:{clip}};}},createAnimal:()=>({root,update(){},isPhysical:()=>false,installBakedAttack(bake,{isCurrent}){attempts++;return new Promise((resolve,reject)=>{finish=()=>{if(!isCurrent())reject(new DOMException('Admission obsolete','AbortError'));else{installed.add(bake.meta.clip);resolve(true);}};});},dispose(){}})});
  try{roster.sync();await flush();await flush();assert.equal(attempts,1);animal.attackId='second';animal.status=nextStatus;roster.sync();finish();await flush();await flush();assert.equal(attempts,1,'a new strike must not recreate the same clip preparation');assert.equal(installed.has('Weapon_Combo'),true);
   animal.status='attacking';animal.attackId='third';roster.sync();await flush();assert.equal(attempts,1);assert.equal(loads,1);
  }finally{roster.dispose();}
 }
});

test('reusable attack preparation still rejects physical ownership changes and removed actors',async()=>{
 for(const change of ['physical','remove']){
  const animal={id:'a',species:'hyena',status:'attacking',animation:'Weapon_Combo',attackId:'first'},state={raid:{animals:[animal]}};let finish,physical=false,installed=0,attempts=0;
  const roster=createWebGpuAnimalRoster({scene:new Scene(),residency:{},state,assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedAttackBank:{get:async()=>({})},createAnimal:()=>({root:new Group(),update(){},isPhysical:()=>physical,installBakedAttack(_bake,{isCurrent}){attempts++;return new Promise((resolve,reject)=>{finish=()=>{if(!isCurrent())reject(new DOMException('Admission invalid','AbortError'));else{installed++;resolve(true);}};});},dispose(){}})});
  try{roster.sync();await flush();await flush();assert.equal(attempts,1);if(change==='physical')physical=true;else{state.raid.animals=[];roster.sync();}finish();await flush();await flush();assert.equal(installed,0,change);assert.equal(attempts,1,change);}finally{roster.dispose();}
 }
});
test('one-tick waiting-to-walking keeps the baked waiting phase until the confirmed boundary',async()=>{
 let now=0,phaseSource;const scene=new Scene(),animal={id:'a',species:'warthog',status:'waiting',path:null,x:0,z:0,heading:0,attackRemaining:0},state={elapsed:5,raid:{animals:[animal]},tasks:[]},clock=createConfirmedHistoricalClock({initialElapsed:5,now:()=>now}),source=new MeshBasicNodeMaterial(),geometry=new BoxGeometry(),root=new Group();root.position.set(0,2,0);root.add(new Mesh(geometry,source));scene.add(root);
 const roster=createWebGpuAnimalRoster({scene,state,residency:{},renderer:{backend:{isWebGPUBackend:true},library:{fromMaterial:material=>material.clone()}},assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedWalkBank:{get:async()=>({})},experimentalHistoricalMotion:{actorId:'a',clock},createAnimal:options=>(phaseSource=options.phaseSource,{root,update(){root.visible=true;},isBakedWalking:()=>true,isBakedRunning:()=>false,isPhysical:()=>false,installBakedWalk:async()=>false,dispose(){root.removeFromParent();}})});
 try{roster.sync();await flush();await flush();const end=5.02,next={...animal,status:'walking',path:[{x:1,z:0}],x:.07,motionPhase:.02},path={actorId:'a',startStatus:'waiting',endStatus:'walking',continuous:true,timed:true,start:{at:5,x:0,z:0},end:{at:end,x:.07,z:0},segments:[{at:end,t0:5,t1:end,x0:0,z0:0,x1:.07,z1:0}]},preview={sequence:1,start:5,end,safeForAutonomousPlayback:true,reasons:[],clockSegments:{version:1,start:5,end,startPauses:[],endPauses:[],complete:true,segments:[{start:5,end,realDuration:.02,rate:1}]},trace:{actors:[path],actorTickStates:{complete:true,actors:[{actorId:'a',samples:[actorTickState(animal,5),actorTickState(next,end)]}]}},certificates:{actorId:'a',sequence:1,animationSynchronized:true,otherActorsSynchronized:true,effectsSynchronized:true,continuousCollision:true,inputSynchronized:true}},support={sequence:1,valid:()=>true,actors:[{actorId:'a',startHeight:2,endHeight:2,segments:[{...path.segments[0],y0:2,y1:2}]}]};clock.begin(preview);assert.equal(roster.startHistoricalMotion(preview,support),true);now=10;clock.advance();assert.equal(phaseSource.sample(),0);assert.equal(animal.status,'waiting');assert.equal(roster.historicalMotionCurrent(preview),true);now=20;clock.advance();roster.finishHistoricalMotion(preview,{deferHandoff:true});assert.equal(phaseSource.sample(),0,'phase remains owned until the boundary commits');assert.equal(roster.prepareHistoricalMotion(preview,support).reason,'roster-busy');assert.throws(()=>roster.historicalBoundaryCommitted({...preview}),/handoff mismatch/);assert.equal(phaseSource.sample(),0,'failed handoff does not release the phase');roster.historicalBoundaryCommitted(preview);assert.throws(()=>phaseSource.sample(),/unavailable/);assert.equal(animal.status,'waiting');}finally{roster.dispose();clock.dispose();geometry.dispose();source.dispose();}
});
test('frames update only animals with an active visual reconciliation',async()=>{
 const animals=Array.from({length:12},(_,i)=>({id:String(i),species:'hyena',status:'walking',x:i,z:0})),state={elapsed:0,raid:{animals}},actors=new Map(),roster=createWebGpuAnimalRoster({scene:{},residency:{get:()=>null},state,assetBank:{tick(){},dispose(){}},createAnimal:({actorId})=>{const actor={updates:0,checks:0,reconciling:false,update(){this.updates++;},isReconciling(){this.checks++;return this.reconciling;},dispose(){}};actors.set(actorId,actor);return actor;}});
 try{roster.sync();await flush();await flush();for(const actor of actors.values()){actor.updates=0;actor.checks=0;}for(let i=0;i<4;i++)roster.tick(i);assert.ok([...actors.values()].every(actor=>actor.updates===0&&actor.checks===0));const active=actors.get('3');active.reconciling=true;roster.get('3').update();assert.equal(active.updates,1);assert.equal(roster.beginImpact({kind:'castAttack',id:'impact',targetId:'3'}),true);roster.tick(5);assert.equal(active.updates,2);assert.ok([...actors].filter(([id])=>id!=='3').every(([,actor])=>actor.updates===0&&actor.checks===0));roster.resolveImpact('impact',false);assert.equal(active.updates,3);active.reconciling=false;roster.tick(6);assert.equal(active.updates,4);const checks=active.checks;roster.tick(7);assert.equal(active.updates,4);assert.equal(active.checks,checks);state.raid.animals=state.raid.animals.filter(a=>a.id!=='3');roster.sync();roster.tick(8);assert.equal(roster.get('3'),null);}finally{roster.dispose();}
});
test('confirmed uninterrupted attack installs its GPU phase and rejects changed identity',async()=>{
 let now=0,phaseSource,finishWalk,walkInstalls=0,attackingReady=true;const scene=new Scene(),animal={id:'a',species:'hyena',status:'attacking',animation:'Weapon_Combo',attackId:'strike',attackDuration:2,attackRemaining:1.5,x:0,z:0,heading:0},state={elapsed:5,raid:{animals:[animal]}},clock=createConfirmedHistoricalClock({initialElapsed:5,now:()=>now}),source=new MeshBasicNodeMaterial(),geometry=new BoxGeometry(),root=new Group(),mesh=new Mesh(geometry,source);root.position.set(0,2,0);root.add(mesh);scene.add(root);
 const roster=createWebGpuAnimalRoster({scene,state,residency:{},renderer:{backend:{isWebGPUBackend:true},library:{fromMaterial:m=>m.clone()}},assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedWalkBank:{get:()=>new Promise(resolve=>{finishWalk=resolve;})},experimentalHistoricalMotion:{actorId:'a',clock},createAnimal:options=>(phaseSource=options.phaseSource,{root,update(){root.visible=true;},isBakedWalking:()=>false,isBakedAttacking:()=>attackingReady,bakedAttackClip:()=>animal.animation,isPhysical:()=>false,installBakedWalk:async()=>{walkInstalls++;return true;},dispose(){root.removeFromParent();}})});
 try{roster.sync();await flush();await flush();const path={actorId:'a',startStatus:'attacking',endStatus:'attacking',continuous:true,timed:true,start:{at:5,x:0,z:0},end:{at:5.1,x:0,z:0},segments:[{t0:5,t1:5.1,x0:0,z0:0,x1:0,z1:0}]},samples=[actorTickState(animal,5),actorTickState({...animal,attackRemaining:1.4},5.1)],preview={sequence:1,safeForAutonomousPlayback:true,reasons:[],start:5,end:5.1,clockSegments:{version:1,start:5,end:5.1,startPauses:[],endPauses:[],complete:true,segments:[{start:5,end:5.1,realDuration:.1,rate:1}]},trace:{actors:[path],actorTickStates:{complete:true,actors:[{actorId:'a',samples}]}},certificates:{actorId:'a',sequence:1,animationSynchronized:true,otherActorsSynchronized:true,effectsSynchronized:true,continuousCollision:true,inputSynchronized:true}},support={sequence:1,valid:()=>true,actors:[{actorId:'a',startHeight:2,endHeight:2,segments:[{...path.segments[0],y0:2,y1:2}]}]};clock.begin(preview);attackingReady=false;assert.equal(roster.startHistoricalMotion(preview,support),false);attackingReady=true;assert.equal(roster.startHistoricalMotion(preview,support),true);assert.ok(phaseSource.status().installed);finishWalk({meta:{species:"hyena"}});await flush();assert.equal(walkInstalls,0);assert.equal(roster.historicalMotionCurrent(preview),true);now=50;clock.advance();assert.ok(phaseSource.sample()>.5);clock.suspend();const held=phaseSource.sample();now=1000;clock.advance();assert.equal(phaseSource.sample(),held);clock.resume();now=1010;clock.advance();assert.ok(phaseSource.sample()>held);animal.attackId='other';assert.equal(roster.historicalMotionCurrent(preview),false);const abortedPhase=phaseSource.sample();roster.abortHistoricalMotion();now=1030;clock.advance();assert.equal(phaseSource.sample(),abortedPhase,'aborted animation stays at its displayed phase even if the clock changes');roster.cancelHistoricalMotion();assert.equal(phaseSource.status().installed,null,'cancel releases the retained phase');await flush();await flush();assert.equal(walkInstalls,1);roster.dispose();assert.equal(phaseSource.status().closed,true,'roster disposal releases the retained phase');}finally{roster.dispose();clock.dispose();geometry.dispose();source.dispose();}
});
test('attack clip preparation is retained across confirmed action changes',async()=>{
 const animal={id:'a',species:'hyena',status:'attacking',animation:'Weapon_Combo',attackId:'first'},state={raid:{animals:[animal]}},loads=[],installs=[];let finish;
 const roster=createWebGpuAnimalRoster({scene:{},residency:{},state,assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedAttackBank:{get(species,clip){loads.push([species,clip]);return new Promise(resolve=>{finish=resolve;});}},createAnimal:()=>({root:new Group(),update(){},installBakedAttack:async(_bake,{isCurrent})=>{installs.push(isCurrent());return true;},dispose(){}})});
 try{roster.sync();await flush();await flush();assert.deepEqual(loads,[['hyena','Weapon_Combo']]);animal.status='walking';roster.sync();finish({});await flush();assert.deepEqual(installs,[true]);animal.status='attacking';animal.attackId='second';roster.sync();await flush();assert.deepEqual(installs,[true]);roster.sync();await flush();assert.equal(loads.length,1);}finally{roster.dispose();}
});
test('production provisional fall bank is shared and does not enable geometric support',async()=>{
 const animals=['a','b'].map(id=>({id,species:'hyena',status:'walking',x:0,z:0,radius:.7})),state={elapsed:1,raid:{animals}},before=structuredClone(state),created=[],bank=new Map([['hyena:front',{}]]);let loads=0,finish;
 const roster=createWebGpuAnimalRoster({scene:{},residency:{get:()=>null},state,assetBank:{tick(){},dispose(){}},provisionalBakedFall:true,loadProvisionalFalls:()=>{loads++;return new Promise(resolve=>{finish=resolve;});},createAnimal:options=>{created.push(options);return {update(){},dispose(){}};}});
 try{roster.sync();await flush();assert.equal(loads,0);assert.equal(created.length,2);for(const options of created){assert.equal(options.experimentalPoseReconciliation,false);assert.equal(options.reconcileImpactPose,true);assert.equal(options.getFalls(),null);}assert.equal(roster.beginImpact({kind:'castAttack',id:'one',targetId:'a'}),true);assert.equal(roster.beginImpact({kind:'castAttack',id:'two',targetId:'b'}),true);await flush();assert.equal(loads,1);finish(bank);await flush();for(const options of created)assert.equal(options.getFalls(),bank);assert.equal(roster.status().fallsReady,true);assert.deepEqual(state,before);}
 finally{roster.dispose();}
});
