test('real animal roster continues two confirmed slices under one publication version',async()=>{let now=0,updates=0;const scene=new Scene(),animal={id:'a',species:'warthog',status:'waiting',path:[{x:0,z:2}],x:0,z:0,heading:0,motionPhase:3,attackRemaining:0},state={elapsed:5,raid:{animals:[animal]},tasks:[]},clock=createConfirmedHistoricalClock({initialElapsed:5,now:()=>now}),material=new MeshBasicNodeMaterial(),geometry=new BoxGeometry(),root=new Group();root.position.set(0,2,0);root.add(new Mesh(geometry,material));scene.add(root);const roster=createWebGpuAnimalRoster({scene,state,residency:{},renderer:{backend:{isWebGPUBackend:true},library:{fromMaterial:m=>m.clone()}},assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedWalkBank:{get:async()=>{throw Error('no bake');}},historicalDiagnostics:true,experimentalHistoricalMotion:{actorId:'a',clock},createAnimal:()=>({root,update(){updates++;root.visible=true;root.position.set(animal.x,2,animal.z);},isBakedWalking:()=>false,isBakedRunning:()=>false,isBakedAttacking:()=>false,isPhysical:()=>false,dispose(){root.removeFromParent();}})});const make=(start,end,first,last)=>{const path={actorId:'a',startStatus:'waiting',endStatus:'waiting',continuous:true,timed:true,start:{at:start,x:first.x,z:first.z},end:{at:end,x:last.x,z:last.z},segments:[{at:end,t0:start,t1:end,x0:first.x,z0:first.z,x1:last.x,z1:last.z}]},preview={sequence:1,start,end,safeForAutonomousPlayback:true,reasons:[],clockSegments:{version:1,start,end,startPauses:[],endPauses:[],complete:true,segments:[{start,end,realDuration:end-start,rate:1}]},trace:{actors:[path],actorTickStates:{complete:true,actors:[{actorId:'a',samples:[actorTickState(first,start),actorTickState(last,end)]}]}},certificates:{actorId:'a',sequence:1,animationSynchronized:true,otherActorsSynchronized:true,effectsSynchronized:true,continuousCollision:true,inputSynchronized:true}},support={sequence:1,valid:()=>true,actors:[{actorId:'a',startHeight:2,endHeight:2,segments:[{...path.segments[0],y0:2,y1:2}]}]};return {preview,support};};try{roster.sync();await flush();await flush();await flush();const first={...animal},middle={...animal,z:.06,motionPhase:3.04},last={...animal,z:.12,motionPhase:3.08},a=make(5,5.04,first,middle),b=make(5.04,5.08,middle,last),full={...a.preview,end:5.08,clockSegments:{version:1,start:5,end:5.08,startPauses:[],endPauses:[],complete:true,segments:[{start:5,end:5.08,realDuration:.08,rate:1}]}};clock.begin(full);assert.equal(roster.prepareHistoricalMotion(a.preview,a.support).ok,true,JSON.stringify(roster.prepareHistoricalMotion(a.preview,a.support)));assert.equal(roster.startHistoricalMotion(a.preview,a.support),true,'first start');now=40;assert.equal(clock.advanceUntil(5.04),5.04);assert.equal(roster.canFinishHistoricalMotion(a.preview,{continuation:true}),true);roster.finishHistoricalMotion(a.preview,{continuation:true});Object.assign(animal,middle);state.elapsed=5.04;roster.sync();assert.equal(root.position.z,.06);assert.equal(roster.startHistoricalMotion(b.preview,b.support),true);roster.cancelHistoricalMotion();assert.equal(root.position.z,.06,'rollback preserves the committed endpoint');assert.equal(clock.elapsed,5.04);assert.ok(clock.status().active,'the shared clock is not cancelled');assert.deepEqual(animal,middle,'rollback does not mutate the authoritative actor');assert.equal(roster.startHistoricalMotion(b.preview,b.support),true,'the same continuation can be reinstalled');clock.releaseLimit(5.04);now=80;assert.equal(clock.advanceUntil(5.08),5.08);roster.finishHistoricalMotion(b.preview);assert.equal(root.position.z,.06);assert.ok(updates>0);}finally{roster.dispose();clock.dispose();geometry.dispose();material.dispose();}});

test('real animal roster carries continuation across a certified stationary slice',async()=>{let now=0,updates=0;const scene=new Scene(),animal={id:'a',species:'warthog',status:'waiting',path:[{x:0,z:2}],x:0,z:0,heading:0,motionPhase:3,attackRemaining:0},state={elapsed:5,raid:{animals:[animal]},tasks:[]},clock=createConfirmedHistoricalClock({initialElapsed:5,now:()=>now}),material=new MeshBasicNodeMaterial(),geometry=new BoxGeometry(),root=new Group();root.position.set(0,2,0);root.add(new Mesh(geometry,material));scene.add(root);const roster=createWebGpuAnimalRoster({scene,state,residency:{},renderer:{backend:{isWebGPUBackend:true},library:{fromMaterial:m=>m.clone()}},assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedWalkBank:{get:async()=>{throw Error('no bake');}},historicalDiagnostics:true,experimentalHistoricalMotion:{actorId:'a',clock},createAnimal:()=>({root,update(){updates++;root.visible=true;root.position.set(animal.x,2,animal.z);},isBakedWalking:()=>false,isBakedRunning:()=>false,isBakedAttacking:()=>false,isPhysical:()=>false,dispose(){root.removeFromParent();}})});const make=(start,end,first,last)=>{const path={actorId:'a',startStatus:'waiting',endStatus:'waiting',continuous:true,timed:true,start:{at:start,x:first.x,z:first.z},end:{at:end,x:last.x,z:last.z},segments:[{at:end,t0:start,t1:end,x0:first.x,z0:first.z,x1:last.x,z1:last.z}]},preview={sequence:1,start,end,safeForAutonomousPlayback:true,reasons:[],clockSegments:{version:1,start,end,startPauses:[],endPauses:[],complete:true,segments:[{start,end,realDuration:end-start,rate:1}]},trace:{actors:[path],actorTickStates:{complete:true,actors:[{actorId:'a',samples:[actorTickState(first,start),actorTickState(last,end)]}]}},certificates:{actorId:'a',sequence:1,animationSynchronized:true,otherActorsSynchronized:true,effectsSynchronized:true,continuousCollision:true,inputSynchronized:true}},support={sequence:1,valid:()=>true,actors:[{actorId:'a',startHeight:2,endHeight:2,segments:[{...path.segments[0],y0:2,y1:2}]}]};return {preview,support};};try{roster.sync();await flush();await flush();await flush();const first={...animal},middle={...animal,z:.06,motionPhase:3.04},last={...animal,z:.12,motionPhase:3.08},a=make(5,5.04,first,middle),b=make(5.04,5.06,middle,middle),c=make(5.06,5.1,middle,last),full={...a.preview,end:5.1,clockSegments:{version:1,start:5,end:5.1,startPauses:[],endPauses:[],complete:true,segments:[{start:5,end:5.1,realDuration:.1,rate:1}]}};clock.begin(full);assert.equal(roster.prepareHistoricalMotion(a.preview,a.support).ok,true,JSON.stringify(roster.prepareHistoricalMotion(a.preview,a.support)));assert.equal(roster.startHistoricalMotion(a.preview,a.support),true,'first start');now=40;assert.equal(clock.advanceUntil(5.04),5.04);assert.equal(roster.canFinishHistoricalMotion(a.preview,{continuation:true}),true);roster.finishHistoricalMotion(a.preview,{continuation:true});Object.assign(animal,middle);state.elapsed=5.04;roster.sync();assert.equal(roster.startHistoricalMotion(b.preview,b.support),true);clock.releaseLimit(5.04);now=60;assert.equal(clock.advanceUntil(5.06),5.06);assert.equal(roster.canFinishHistoricalMotion(b.preview,{continuation:true}),true);roster.finishHistoricalMotion(b.preview,{continuation:true});state.elapsed=5.06;roster.sync();assert.equal(roster.startHistoricalMotion(c.preview,c.support),true);clock.releaseLimit(5.06);now=100;assert.equal(clock.advanceUntil(5.1),5.1);roster.finishHistoricalMotion(c.preview);assert.equal(root.position.z,.06);assert.ok(updates>0);}finally{roster.dispose();clock.dispose();geometry.dispose();material.dispose();}});

test('committing a removed or replaced animal never resets its successor phase',async()=>{
 for(const replacement of [false,true]){
  let now=0;const phases=[],scene=new Scene(),animal={id:'a',species:'warthog',status:'waiting',path:null,x:0,z:0,heading:0,attackRemaining:0},state={elapsed:5,raid:{animals:[animal]}},clock=createConfirmedHistoricalClock({initialElapsed:5,now:()=>now}),source=new MeshBasicNodeMaterial(),geometry=new BoxGeometry();
  const roster=createWebGpuAnimalRoster({scene,state,residency:{},renderer:{backend:{isWebGPUBackend:true},library:{fromMaterial:material=>material.clone()}},assetBank:{tick(){},dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedWalkBank:{get:async()=>({})},experimentalHistoricalMotion:{actorId:'a',clock},createAnimal:options=>{phases.push(options.phaseSource);const root=new Group();root.position.set(0,2,0);root.add(new Mesh(geometry,source));scene.add(root);return {root,update(){root.visible=true;},isBakedWalking:()=>true,isBakedRunning:()=>false,isPhysical:()=>false,installBakedWalk:async()=>false,dispose(){root.removeFromParent();}};}});
  try{roster.sync();await flush();await flush();const end=5.02,next={...animal,status:'walking',path:[{x:1,z:0}],x:.07,motionPhase:.02},path={actorId:'a',startStatus:'waiting',endStatus:'walking',continuous:true,timed:true,start:{at:5,x:0,z:0},end:{at:end,x:.07,z:0},segments:[{at:end,t0:5,t1:end,x0:0,z0:0,x1:.07,z1:0}]},preview={sequence:1,start:5,end,safeForAutonomousPlayback:true,reasons:[],clockSegments:{version:1,start:5,end,startPauses:[],endPauses:[],complete:true,segments:[{start:5,end,realDuration:.02,rate:1}]},trace:{actors:[path],actorTickStates:{complete:true,actors:[{actorId:'a',samples:[actorTickState(animal,5),actorTickState(next,end)]}]}},certificates:{actorId:'a',sequence:1,animationSynchronized:true,otherActorsSynchronized:true,effectsSynchronized:true,continuousCollision:true,inputSynchronized:true}},support={sequence:1,valid:()=>true,actors:[{actorId:'a',startHeight:2,endHeight:2,segments:[{...path.segments[0],y0:2,y1:2}]}]};clock.begin(preview);assert.equal(roster.startHistoricalMotion(preview,support),true);now=20;clock.advance();roster.finishHistoricalMotion(preview,{deferHandoff:true});const oldPhase=phases[0];assert.ok(oldPhase.status().installed);state.raid.animals=replacement?[{...animal,species:'hyena'}]:[];roster.sync();assert.equal(oldPhase.status().closed,true);await flush();await flush();if(replacement){assert.equal(phases.length,2);phases[1].install([{at:5,phase:3},{at:end,phase:3.02}],preview);assert.ok(phases[1].status().installed);}assert.doesNotThrow(()=>roster.historicalBoundaryCommitted(preview));if(replacement)assert.ok(phases[1].status().installed,'successor animation must remain installed');assert.throws(()=>roster.historicalBoundaryCommitted(preview),/handoff mismatch/);
  }finally{roster.dispose();clock.dispose();geometry.dispose();source.dispose();}
 }
});

test('animal run download retries without a publication and keeps the confirmed rig',async()=>{
 const entity={id:'a',species:'hyena',status:'entering'},state={raid:{animals:[entity]}},bank={tick(){},dispose(){}};let requests=0,installs=0,created=0;
 const roster=createWebGpuAnimalRoster({scene:{},residency:{},state,assetBank:bank,walkRetryDelay:5,pipelineAdmission:{prepare:async()=>{}},bakedRunBank:{get(){if(++requests===1)return Promise.reject(Error('temporary'));return Promise.resolve({meta:{species:'hyena'}});}},createAnimal:()=>{created++;return {root:new Group(),update(){this.root.visible=true;},async installBakedRun(){installs++;return true;},dispose(){}};}});
 try{roster.sync();await flush();await flush();assert.equal(requests,1);assert.equal(roster.get('a').root.visible,true);await new Promise(resolve=>setTimeout(resolve,35));await flush();assert.equal(requests,2);assert.equal(installs,1);assert.equal(created,1);}finally{roster.dispose();}
});
test('run retries are bounded, stop on removal, and do not retry admission errors',async()=>{
 const animals=[{id:'a',species:'hyena',status:'entering'},{id:'b',species:'lion',status:'entering'},{id:'c',species:'rhino',status:'entering'}],state={raid:{animals}},calls=[],bank={tick(){},dispose(){}};
 const roster=createWebGpuAnimalRoster({scene:{},residency:{},state,assetBank:bank,walkRetryDelay:5,pipelineAdmission:{prepare:async()=>{}},bakedRunBank:{get(species){calls.push(species);return species==='rhino'?Promise.resolve({}):Promise.reject(Error('unavailable'));}},createAnimal:()=>({root:new Group(),update(){this.root.visible=true;},async installBakedRun(){throw Error('admission failed');},dispose(){}})});
 try{roster.sync();await flush();await flush();animals.splice(1,1);roster.sync();await new Promise(resolve=>setTimeout(resolve,100));assert.equal(calls.filter(x=>x==='hyena').length,4);assert.equal(calls.filter(x=>x==='lion').length,1);assert.equal(calls.filter(x=>x==='rhino').length,1);assert.equal(roster.get('a').root.visible,true);}finally{roster.dispose();}
});

test('leaving a running state cancels a pending run download retry',async()=>{
 const entity={id:'a',species:'hyena',status:'entering'},state={raid:{animals:[entity]}},bank={tick(){},dispose(){}};let attempts=0;
 const roster=createWebGpuAnimalRoster({scene:{},residency:{},state,assetBank:bank,walkRetryDelay:30,pipelineAdmission:{prepare:async()=>{}},bakedRunBank:{get(){attempts++;return Promise.reject(Error('temporary'));}},createAnimal:()=>({root:new Group(),update(){this.root.visible=true;},dispose(){}})});
 try{roster.sync();await flush();await flush();entity.status='attacking';roster.sync();await new Promise(resolve=>setTimeout(resolve,100));assert.equal(attempts,1);assert.equal(roster.get('a').root.visible,true);}finally{roster.dispose();}
});
